      if (tab.name == 'first') {
        this.realtime = true
        this.playback = false
        this.$refs.new.changeWndNum('2')
      } else if (tab.name == 'second') {
        this.realtime = false
        this.playback = true
        this.$refs.new.changeWndNum('1')
      }
    },
    getVideoUrl() {
      // this.videoOpen = false;
      // getLiveStreamUrl(this.queryParams).then(response => {
      if (this.realtime == true) {
        // 测试rtsp流
        this.video1 = this.queryParams.apeId;
        this.$refs.video1.channel_id = this.video1;
        this.$refs.video1.start();
      } else {
        if (this.startTime == '' || this.playback == '') {
          this.$message({
            type: 'warning',
            message: '请选选择开始、结束时间'
          })
        } else {
          let start = this.startTime;
          let end = this.endTime;
          let { prevMinute, nextMinute } = this.getAdjacentMinutes2(start, end);
          let msg = {
            channel_id: this.queryParams.apeId,
            record_type: 1,
            start_time: prevMinute,
            end_time: nextMinute,
            show_timebar: 1,
          }
          this.$refs.video2.form = msg;
          this.$refs.video2.start();
        }
      }
    },
    // 处理用户自定义回放时间
    getAdjacentMinutes2(dateTime1, dateTime2) {
      const date_start = new Date(dateTime1);
      const date_end = new Date(dateTime2);
      const start = new Date(date_start.getTime()); // 前一分钟
      const end = new Date(date_end.getTime()); // 后一分钟

      const formatDate = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const seconds = String(date.getSeconds()).padStart(2, '0');

        return `${year}${month}${day}${hours}${minutes}${seconds}`;
      };

      const prevMinuteFormatted = formatDate(start);
      const nextMinuteFormatted = formatDate(end);

      return {
        prevMinute: prevMinuteFormatted,
        nextMinute: nextMinuteFormatted
      };
    },
    // 处理时间函数
    formatDate(date) {
      const year = date.getFullYear();
      const month = `0${date.getMonth() + 1}`.slice(-2);
      const day = `0${date.getDate()}`.slice(-2);
      const hours = `0${date.getHours()}`.slice(-2);
      const minutes = `0${date.getMinutes()}`.slice(-2);
      const seconds = `0${date.getSeconds()}`.slice(-2);
