          type: 'error',
        });
        return;
      }

      if (!this.hisVideoMsg.startTime || !this.hisVideoMsg.endTime) {
        this.$message({
          message: '开始时间和结束时间不能为空！',
          type: 'error',
        });
        return;
      }
      // 搜索
      let oLiveView = {
        szIP: item.parent_ip, // 设备的 IP 地址或者普通域名(比如花生壳域名)
        szPort: '80', // 登录设备的 http/https 端口号，根据 iPrototocol 选择传入不同的端口
