        console.log("搜索回放检查", result);

        const items = result.CMSearchResult.matchList[0].searchMatchItem; // 根据实际 XML 结构修改

        this.fileBackVideo = [];
        items.forEach((item, i) => {
          const szPlaybackURI = item.playbackURI[0]; // 根据实际 XML 结构修改
          const szStartTime = item.startTime[0]; // 根据实际 XML 结构修改
          const szEndTime = item.endTime[0]; // 根据实际 XML 结构修改
          const szFileName = new URL(szPlaybackURI).searchParams.get('name');

          this.fileBackVideo.push({
            fileName: szFileName,
            startTime: szStartTime.replace("T", " ").replace("Z", ""),
            endTime: szEndTime.replace("T", " ").replace("Z", ""),
            playbackURI: szPlaybackURI,
          });
        });

      } catch (error) {
        console.error("搜索失败:", error);
      }
    },
